fn defensive_crisis(version, rnd, player, data, target, debug) -> (bool, bool)

// ---- L19
tps = data.context.setting.tick_per_second            // *(*(data+8)+8)+0x12f8
enemy = 1 - player.info.team                          // team>=2 면 panic_bounds_check(enemy, 2)

// ---- L21~28 : 근처 적 챔피언 수집 (bump 아레나)
near_enemies: Vec<&Entity> =
    data.cache.player_champion[enemy]                 // [Option<&Entity>;5]
      .iter().filter_map(Some)                        // iter_champions — None 슬롯 제거
      .filter(|e| CLOSURE_0(e))                       // 아래 참조. 본문에 인라인 안 됨
      .collect_in(data.context.pool)

// ---- L30 : 하나도 없으면 즉시 (false, false)
if near_enemies.len() == 0 { return (false, false) }  // check_kill_die_tick 도 호출 안 됨

// ---- L32~35 : 대상이 곧 죽는가
die_imminent = false
tp = data.cache.player_by_champion_id(target.id)
if tp != null {
    die = fight_check::check_kill_die_tick(
            version, rnd, data, tp, target,
            near_enemies.clone(),      // bump clone
            Vec::new_in(pool),         // 빈 Vec (두 번째 엔티티 목록 자리)
            debug)
    die_imminent = die < tps * 2       // IR: shl tps,1
}

// ---- L40~50 : 근처 적 중 '즉시 쓸 수 있는 CC 스킬' 보유자 탐색
for e in &near_enemies {                               // L41 closure$1
    // L42~46 : (효과, 남은쿨) 3쌍
    ch = if e.ty == EntityType::Champion { Some(&e.ty.payload) } else { None }
    slots = [
      (&e.skill_effect,                                 ch.map_or(0, |c| c.skill_cooldown)),   // L43
      (if e.level > 2 { &e.skill2_effect } else { &NONE }, ch.map_or(0, |c| c.skill2_cooldown)), // L44
      (if e.level > 4 { &e.ult_effect   } else { &NONE }, ch.map_or(0, |c| c.ult_cooldown)),   // L45
    ]
    // L47~48 : 세 슬롯 중 하나라도
    if slots.iter().any(|(eff, cd)|
           *cd <= tps                                   // 쿨 1초 이하 (cd>tps 면 스킵)
        && eff.is_some()                                // 판별자 != -1
        && fight_check::effect_cc_time(version, eff.unwrap()).is_some()  // 반환 Option<usize> 의 tag==1
       ) { return (die_imminent, true) }
}
return (die_imminent, false)                            // L53

// ================= CLOSURE_0 (필터 술어) =================
// 본문에 인라인되지 않음. 실체 = m10.ll:55868~55953
//   @_RNvXs1_...implsQNCNvNtCs..._7game_ai10buff_value16defensive_crisis0...call_mut
// 캡처 env(48B) = { +0 target, +8 &version, +16 player, +24/+32 data.cache.game(&dyn, data+vtable), +40 data.blackboard }
fn CLOSURE_0(e: &Entity) -> bool {
    r  = plan_legacy::old::battle::max_range(e, target)                 // L23
    d2 = (e.x - target.x)^2 + (e.y - target.y)^2                        // abs 차이의 제곱합, Entity+0x660/+0x668
    if d2 > (r + 30000)^2 { return false }                              // L24
    if e.team == TeamType::Player(enemy)                                // Entity+0x0 tag==0, payload +0x8
       && path_finder::is_enemy_well_danger(version, player, e.x, e.y)  // L25
       { return false }
    return data.blackboard[enemy].is_recent_visible(                    // L26
               data.cache.game /*&dyn*/, player, e)
}
